insert into pages (id, slug, type, parent_id, title, language_code, translation_group_id, meta_title, meta_description, canonical_url, featured_image, status, publish_date) values
('00000000-0000-0000-0000-000000000001', '', 'tool', NULL, 'Homepage (Who Called Me)', 'en-GB', '00000000-0000-0000-0000-000000000001', 'Who Called Me? Check Unknown Numbers — MyRingCheck', 'Check any unknown UK number for free. See spam reports, a 0-100 spam score and what other people reported — no sign-up needed.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000002', 'about-us', 'foundational', NULL, 'About Us', 'en-GB', '00000000-0000-0000-0000-000000000002', 'About Us — MyRingCheck', 'About MyRingCheck — why we built a free unknown-number checker for the UK.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000003', 'contact-us', 'foundational', NULL, 'Contact Us', 'en-GB', '00000000-0000-0000-0000-000000000003', 'Contact Us — MyRingCheck', 'Contact MyRingCheck — ask a question, request a number removal, or correct a report.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000004', 'how-it-works', 'foundational', NULL, 'How It Works', 'en-GB', '00000000-0000-0000-0000-000000000004', 'How It Works — MyRingCheck', 'How MyRingCheck works: search a number, read the reports, check the score, vote or report.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000005', 'spam-score', 'foundational', NULL, 'How We Calculate Spam Score', 'en-GB', '00000000-0000-0000-0000-000000000005', 'How We Calculate the Spam Score — MyRingCheck', 'How the MyRingCheck 0-100 spam score is calculated — reports, votes, recency and pattern signals, explained simply.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000006', 'report-a-number', 'tool', NULL, 'Report a Number', 'en-GB', '00000000-0000-0000-0000-000000000006', 'Report a Number — MyRingCheck', 'Report a scam or nuisance number. Your report is checked, then published to warn the next person.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000007', 'privacy-policy', 'foundational', NULL, 'Privacy Policy', 'en-GB', '00000000-0000-0000-0000-000000000007', 'Privacy Policy — MyRingCheck', 'How MyRingCheck uses your data — what we collect, what we never publish, and your rights.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000008', 'terms-and-conditions', 'foundational', NULL, 'Terms & Conditions', 'en-GB', '00000000-0000-0000-0000-000000000008', 'Terms & Conditions — MyRingCheck', 'Rules for using MyRingCheck — reports, moderation, and what the score does and does not mean.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000009', 'disclaimer', 'foundational', NULL, 'Disclaimer', 'en-GB', '00000000-0000-0000-0000-000000000009', 'Disclaimer — MyRingCheck', 'Disclaimer — the spam score is a signal, not a guarantee, and caller location can be spoofed.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000010', 'cookie-policy', 'foundational', NULL, 'Cookie Policy', 'en-GB', '00000000-0000-0000-0000-000000000010', 'Cookie Policy — MyRingCheck', 'How MyRingCheck uses cookies — necessary, analytics and advertising cookies, and how to turn them off.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000011', 'top-reported-numbers', 'foundational', NULL, 'Top Reported Numbers', 'en-GB', '00000000-0000-0000-0000-000000000011', 'Top Reported Numbers — MyRingCheck', 'The most reported scam and nuisance numbers in the UK, updated daily from community reports.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000012', 'latest-reports', 'foundational', NULL, 'Latest Reports', 'en-GB', '00000000-0000-0000-0000-000000000012', 'Latest Reports — MyRingCheck', 'The latest scam and nuisance call reports from the MyRingCheck community.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000013', 'reverse-phone-lookup', 'foundational', NULL, 'Reverse Phone Lookup UK', 'en-GB', '00000000-0000-0000-0000-000000000013', 'Reverse Phone Lookup UK — MyRingCheck', 'What reverse phone lookup means in the UK — what you can find out for free, and what you cannot.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000014', 'scam-calls', 'hub', NULL, 'Scam Calls', 'en-GB', '00000000-0000-0000-0000-000000000014', 'Scam Calls — MyRingCheck', 'The main scam call types in the UK — HMRC, bank, delivery and more — and what to do about each one.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000015', 'hmrc-scam-calls', 'subpage', '00000000-0000-0000-0000-000000000014', 'HMRC Scam Calls', 'en-GB', '00000000-0000-0000-0000-000000000015', 'HMRC Scam Calls — MyRingCheck', 'HMRC scam calls explained — the three scripts, what HMRC actually does, and what to do if you get one.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000016', 'bank-scam-calls', 'subpage', '00000000-0000-0000-0000-000000000014', 'Bank Scam Calls', 'en-GB', '00000000-0000-0000-0000-000000000016', 'Bank Scam Calls — MyRingCheck', 'Bank scam calls explained — the safe account trick, what your bank will never ask, and calling 159.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000017', 'area-codes', 'hub', NULL, 'Area Codes', 'en-GB', '00000000-0000-0000-0000-000000000017', 'UK Area Codes — MyRingCheck', 'UK area codes explained — what a number''s prefix tells you, and what it does not.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000018', '020', 'subpage', '00000000-0000-0000-0000-000000000017', 'London — 020', 'en-GB', '00000000-0000-0000-0000-000000000018', 'London 020 Area Code — MyRingCheck', 'The 020 London area code — what it means, why scammers spoof it, and how to check a 020 number.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000019', '07-mobile-numbers', 'subpage', '00000000-0000-0000-0000-000000000017', 'Mobile Numbers — 07 Range', 'en-GB', '00000000-0000-0000-0000-000000000019', 'UK 07 Mobile Numbers — MyRingCheck', 'The UK 07 mobile range — why most scam calls come from 07 numbers, and how to check one.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000020', 'report-scam-call-uk', 'pillar', NULL, 'How to Report a Scam Call in the UK', 'en-GB', '00000000-0000-0000-0000-000000000020', 'How to Report a Scam Call in the UK — MyRingCheck', 'How to report a scam call in the UK — 7726 for texts, 159 for bank scams, Action Fraud, and reporting the number here.', '', '', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000101', 'report-scam-text-7726', 'blog', NULL, 'How to Report a Scam Text to 7726 (UK)', 'en-GB', '00000000-0000-0000-0000-000000000101', 'How to Report a Scam Text to 7726 (UK) — MyRingCheck', 'Forward a scam text to 7726 for free. Step by step: what 7726 is, what to forward, and what happens next.', '', '/blog-7726.svg', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000102', '159-bank-scam-number', 'blog', NULL, '159: The Number to Call If a Bank Scam Call Comes In', 'en-GB', '00000000-0000-0000-0000-000000000102', '159: The Number to Call If a Bank Scam Call Comes In — MyRingCheck', 'What is 159? Hang up on a bank scam call, then dial 159 yourself to reach your own bank''s fraud team.', '', '/blog-159.svg', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000103', 'block-unknown-number', 'blog', NULL, 'How to Block an Unknown Number on iPhone and Android (UK)', 'en-GB', '00000000-0000-0000-0000-000000000103', 'How to Block an Unknown Number on iPhone and Android (UK) — MyRingCheck', 'Block an unknown number on iPhone and Android, use Silence Unknown Callers, and report the number afterwards.', '', '/blog-block.svg', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000104', 'missed-call-unknown-number', 'blog', NULL, 'Missed Call from an Unknown Number? Should You Call Back?', 'en-GB', '00000000-0000-0000-0000-000000000104', 'Missed Call from an Unknown Number? Should You Call Back? — MyRingCheck', 'A missed call from an unknown number? Check it first. Three checks before you call back, and the one-ring Wangiri warning.', '', '/blog-missed.svg', 'published', '2026-11-21'),
('00000000-0000-0000-0000-000000000105', '020-number-spoofing', 'blog', NULL, 'Why a London (020) Number Can Call You from Abroad — Spoofing Explained', 'en-GB', '00000000-0000-0000-0000-000000000105', 'Why a London (020) Number Can Call You from Abroad — MyRingCheck', 'A 020 number does not mean the caller is in London. Caller ID spoofing explained, and how to spot it.', '', '/blog-spoofing.svg', 'published', '2026-11-21')
