insert into variables (id, section_id, name, value_html, sort_order) values
('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'hero_heading', '<h1>Who called me?</h1>', 0),
('20000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000001', 'hero_subtext', '<p>Enter any unknown UK number and see, in seconds, whether other people reported it as a scam. Free. No sign-up needed.</p>', 1),
('20000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000001', 'search_label', 'Search an unknown number', 2),
('20000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000001', 'search_placeholder', 'e.g. 020 7946 0958', 3),
('20000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000001', 'search_button_text', 'Check this number', 4),
('20000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000001', 'search_hint', 'Free. No sign-up needed. We never publish a number owner''s name or address.', 5),
('20000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000001', 'search_error_empty', 'Please enter a number first.', 6),
('20000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000001', 'search_error_invalid', 'That does not look like a UK number. Check the digits and try again.', 7),
('20000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000001', 'result_unknown_heading', 'Unknown — No reports yet', 8),
('20000000-0000-0000-0000-000000000010', '10000000-0000-0000-0000-000000000001', 'result_unknown_text', 'Nobody has reported this number yet. That does not mean it is safe — it only means we have no evidence about it.', 9),
('20000000-0000-0000-0000-000000000011', '10000000-0000-0000-0000-000000000001', 'result_first_report_cta', 'Be the first to report it', 10),
('20000000-0000-0000-0000-000000000012', '10000000-0000-0000-0000-000000000001', 'result_score_label', 'Spam score', 11),
('20000000-0000-0000-0000-000000000013', '10000000-0000-0000-0000-000000000001', 'result_reports_label', 'Reports', 12),
('20000000-0000-0000-0000-000000000014', '10000000-0000-0000-0000-000000000001', 'result_origin_label', 'Number origin', 13),
('20000000-0000-0000-0000-000000000015', '10000000-0000-0000-0000-000000000001', 'result_origin_note', 'This is where the number was allocated, not where the caller is — the caller may be anywhere, and the number may be spoofed.', 14),
('20000000-0000-0000-0000-000000000016', '10000000-0000-0000-0000-000000000001', 'vote_safe_button', 'Safe', 15),
('20000000-0000-0000-0000-000000000017', '10000000-0000-0000-0000-000000000001', 'vote_unsafe_button', 'Unsafe / Spam', 16),
('20000000-0000-0000-0000-000000000018', '10000000-0000-0000-0000-000000000001', 'vote_thanks', 'Thanks — your vote has been counted.', 17),
('20000000-0000-0000-0000-000000000019', '10000000-0000-0000-0000-000000000001', 'report_heading', 'Report this number', 18),
('20000000-0000-0000-0000-000000000020', '10000000-0000-0000-0000-000000000001', 'report_submit_button', 'Submit report', 19),
('20000000-0000-0000-0000-000000000021', '10000000-0000-0000-0000-000000000001', 'report_thanks', 'Thanks — your report helps warn the next person.', 20),
('20000000-0000-0000-0000-000000000022', '10000000-0000-0000-0000-000000000001', 'trust_note', 'We never publish the number owner''s name or address. We show the evidence, not just a score.', 21),
('20000000-0000-0000-0000-000000000023', '10000000-0000-0000-0000-000000000002', 'how_heading', '<h2>How it works</h2>', 0),
('20000000-0000-0000-0000-000000000024', '10000000-0000-0000-0000-000000000002', 'how_step1', '<h3>1. Search the number</h3><p>Type the full UK number, including the area code. Spaces, +44 and 0044 all work.</p>', 1),
('20000000-0000-0000-0000-000000000025', '10000000-0000-0000-0000-000000000002', 'how_step2', '<h3>2. Read the evidence</h3><p>See reports from other people, the spam score, and what the caller asked for.</p>', 2),
('20000000-0000-0000-0000-000000000026', '10000000-0000-0000-0000-000000000002', 'how_step3', '<h3>3. Decide what to do</h3><p>Block the number, call 159 if it was a bank scam, or forward scam texts to 7726.</p>', 3),
('20000000-0000-0000-0000-000000000027', '10000000-0000-0000-0000-000000000002', 'how_step4', '<h3>4. Vote or report</h3><p>Your vote and report warn the next person who gets the same call.</p>', 4),
('20000000-0000-0000-0000-000000000028', '10000000-0000-0000-0000-000000000003', 'identify_heading', '<h2>Who called me? How to identify an unknown UK caller</h2>', 0),
('20000000-0000-0000-0000-000000000029', '10000000-0000-0000-0000-000000000003', 'identify_intro', '<p>A missed call from a number you do not recognise is not, by itself, a scam. But in the UK it is very often a scam, a sales call, or a wrong number. The fastest check is the number itself: search it here before you call back.</p>', 1),
('20000000-0000-0000-0000-000000000030', '10000000-0000-0000-0000-000000000003', 'identify_h3_1', '<h3>Start with where the number is allocated</h3><p>020 is London, 0161 is Manchester, 07 is a UK mobile. That tells you where the number was issued — not where the caller is sitting. A scammer anywhere in the world can show a London number.</p>', 2),
('20000000-0000-0000-0000-000000000031', '10000000-0000-0000-0000-000000000003', 'identify_h3_2', '<h3>Then read what other people reported</h3><p>Reports are the real evidence. If ten people say the same number pretended to be HMRC, that is a pattern, not a guess.</p>', 3),
('20000000-0000-0000-0000-000000000032', '10000000-0000-0000-0000-000000000003', 'identify_h3_3', '<h3>No reports yet? That is an answer too</h3><p>Unknown means unknown. It does not mean safe, and it does not mean a scam. Be careful, and be the first to report it if it turns out to be one.</p>', 4),
('20000000-0000-0000-0000-000000000033', '10000000-0000-0000-0000-000000000004', 'todo_heading', '<h2>What to do when a scam or nuisance number calls you</h2>', 0),
('20000000-0000-0000-0000-000000000034', '10000000-0000-0000-0000-000000000004', 'todo_h3_1', '<h3>Never share a code or bank details on an incoming call</h3><p>No real bank, and no real HMRC officer, will ever ask for your one-time code, your PIN, or your full password on a call they made to you.</p>', 1),
('20000000-0000-0000-0000-000000000035', '10000000-0000-0000-0000-000000000004', 'todo_h3_2', '<h3>If it was a bank scam, call 159</h3><p>Hang up, then dial 159 yourself. It connects you to your own bank''s fraud team. Never call back a number the caller gave you.</p>', 2),
('20000000-0000-0000-0000-000000000036', '10000000-0000-0000-0000-000000000004', 'todo_h3_3', '<h3>Forward scam texts to 7726</h3><p>Forward the message to 7726 — it is free, and it helps mobile networks block the sender.</p>', 3),
('20000000-0000-0000-0000-000000000037', '10000000-0000-0000-0000-000000000005', 'score_heading', '<h2>The spam score, honestly explained</h2>', 0),
('20000000-0000-0000-0000-000000000038', '10000000-0000-0000-0000-000000000005', 'score_text', '<p>Every reported number gets a score from 0 to 100. The score comes only from reports and votes that you can see on the page — never from a secret list. A number with no reports has no score at all: it is Unknown, never Safe. Read the full method on the <a href="/spam-score/">spam score methodology</a> page.</p>', 1),
('20000000-0000-0000-0000-000000000039', '10000000-0000-0000-0000-000000000006', 'hero_heading', '<h1>About Us</h1>', 0),
('20000000-0000-0000-0000-000000000040', '10000000-0000-0000-0000-000000000006', 'hero_subtext', '<p>MyRingCheck is a free community checker for unknown UK numbers. We built it because a missed call should take ten seconds to check — not a leap of faith.</p>', 1),
('20000000-0000-0000-0000-000000000041', '10000000-0000-0000-0000-000000000007', 'mission_heading', '<h2>Why we built MyRingCheck</h2>', 0),
('20000000-0000-0000-0000-000000000042', '10000000-0000-0000-0000-000000000007', 'mission_text', '<p>Every week, millions of people in the UK get calls from numbers they do not recognise. Some are genuine. Many are scams, sales calls, or robocalls. The big caller-ID apps are built for phones, not for a quick web search — and they often show a location that misleads more than it helps.</p>', 1),
('20000000-0000-0000-0000-000000000043', '10000000-0000-0000-0000-000000000007', 'mission_h3', '<h3>Our mission</h3><p>Give every UK caller a fast, honest answer: what do other people say about this number, and what is the evidence?</p>', 2),
('20000000-0000-0000-0000-000000000044', '10000000-0000-0000-0000-000000000008', 'data_heading', '<h2>How our data works</h2>', 0),
('20000000-0000-0000-0000-000000000045', '10000000-0000-0000-0000-000000000008', 'data_h3_1', '<h3>Reports come from people like you</h3><p>When someone gets a suspicious call, they report it here. Reports are checked before they are published.</p>', 1),
('20000000-0000-0000-0000-000000000046', '10000000-0000-0000-0000-000000000008', 'data_h3_2', '<h3>Public alerts add the patterns</h3><p>We also follow public scam alerts from Action Fraud, Ofcom, HMRC and the banks — the patterns, never copied comments.</p>', 2),
('20000000-0000-0000-0000-000000000047', '10000000-0000-0000-0000-000000000008', 'data_h3_3', '<h3>We never publish names or addresses</h3><p>A number is not a person. We show the number, its allocation, and the evidence. We never publish who owns a number.</p>', 3),
('20000000-0000-0000-0000-000000000048', '10000000-0000-0000-0000-000000000009', 'hero_heading', '<h1>Contact Us</h1>', 0),
('20000000-0000-0000-0000-000000000049', '10000000-0000-0000-0000-000000000009', 'hero_subtext', '<p>Use the form below. We read every message and reply as soon as we can.</p>', 1),
('20000000-0000-0000-0000-000000000050', '10000000-0000-0000-0000-000000000010', 'removal_heading', '<h2>Number removal and corrections</h2>', 0),
('20000000-0000-0000-0000-000000000051', '10000000-0000-0000-0000-000000000010', 'removal_text', '<p>If a number that belongs to you is wrongly reported, use the form and choose "Number removal" or "Report correction". Tell us the number and what is wrong, and we will review it. A wrong report is corrected — it is not left up to harm someone.</p>', 1),
('20000000-0000-0000-0000-000000000052', '10000000-0000-0000-0000-000000000010', 'removal_h3', '<h3>What to include in your request</h3><p>The number, what is wrong with the report, and a way for us to contact you if we need more detail.</p>', 2),
('20000000-0000-0000-0000-000000000053', '10000000-0000-0000-0000-000000000011', 'business_heading', '<h2>Business and API enquiries</h2>', 0),
('20000000-0000-0000-0000-000000000054', '10000000-0000-0000-0000-000000000011', 'business_text', '<p>If you run a call-blocking app, a security product or a telecom service and want to talk about our data, choose "Business / API" in the form.</p>', 1),
('20000000-0000-0000-0000-000000000055', '10000000-0000-0000-0000-000000000011', 'business_h3', '<h3>What we can talk about</h3><p>Data licensing, API access, and partnerships — not individual number lookups, which are free on the site.</p>', 2),
('20000000-0000-0000-0000-000000000056', '10000000-0000-0000-0000-000000000012', 'hero_heading', '<h1>How It Works</h1>', 0),
('20000000-0000-0000-0000-000000000057', '10000000-0000-0000-0000-000000000012', 'hero_subtext', '<p>Four steps, about ten seconds. No account, no payment, no app to install.</p>', 1),
('20000000-0000-0000-0000-000000000058', '10000000-0000-0000-0000-000000000013', 'step1', '<h2>Step 1 — Search the number</h2><h3>Type the full number</h3><p>Enter the number exactly as it appeared on your phone, including the area code. Spaces, +44 and 0044 all work.</p>', 0),
('20000000-0000-0000-0000-000000000059', '10000000-0000-0000-0000-000000000013', 'step2', '<h2>Step 2 — Check the origin and type</h2><h3>Allocation, not location</h3><p>We show where the number was allocated (for example, 020 is London) and whether it is a landline, mobile, freephone or VoIP range. The caller''s real location is always shown as Unknown — caller ID can be spoofed.</p>', 1),
('20000000-0000-0000-0000-000000000060', '10000000-0000-0000-0000-000000000013', 'step3', '<h2>Step 3 — Read the reports and the score</h2><h3>Evidence first, score second</h3><p>Reports tell you what the caller actually said or asked for. The 0–100 spam score is only a summary of that evidence.</p>', 2),
('20000000-0000-0000-0000-000000000061', '10000000-0000-0000-0000-000000000013', 'step4', '<h2>Step 4 — Vote or report</h2><h3>Warn the next person</h3><p>Mark the number Safe or Unsafe, or write a short report. Reports are checked before they go live.</p>', 3),
('20000000-0000-0000-0000-000000000062', '10000000-0000-0000-0000-000000000014', 'hero_heading', '<h1>How We Calculate Spam Score</h1>', 0),
('20000000-0000-0000-0000-000000000063', '10000000-0000-0000-0000-000000000014', 'hero_subtext', '<p>Our score is a signal, not a verdict. It is built only from evidence you can see on the number page.</p>', 1),
('20000000-0000-0000-0000-000000000064', '10000000-0000-0000-0000-000000000015', 'formula_heading', '<h2>The formula, in plain words</h2>', 0),
('20000000-0000-0000-0000-000000000065', '10000000-0000-0000-0000-000000000015', 'formula_text', '<p>Each approved report adds to the score, with extra weight when the report is in the scam category. Unsafe votes add a little more; Safe votes pull the score down. Very old reports count less than recent ones, because scammers change numbers quickly.</p>', 1),
('20000000-0000-0000-0000-000000000066', '10000000-0000-0000-0000-000000000015', 'formula_h3', '<h3>What goes into the score</h3><p>Report count, report category, Unsafe vote share, how recent the reports are, and pattern signals — did the caller ask for a one-time code, bank details, or use threats?</p>', 2),
('20000000-0000-0000-0000-000000000067', '10000000-0000-0000-0000-000000000016', 'bands_heading', '<h2>Score bands</h2>', 0),
('20000000-0000-0000-0000-000000000068', '10000000-0000-0000-0000-000000000016', 'bands_text', '<p><strong>Unknown (no reports):</strong> no score at all — we know nothing about this number yet. <strong>Low (under 25):</strong> few negative signals. <strong>Medium (25–49):</strong> some negative reports. <strong>High (50–74):</strong> many reports or a clear scam pattern. <strong>Dangerous (75–100):</strong> a strong, repeated scam pattern.</p>', 1),
('20000000-0000-0000-0000-000000000069', '10000000-0000-0000-0000-000000000016', 'bands_h3', '<h3>Why evidence matters more than the score</h3><p>Two numbers can have the same score for different reasons. Always read the reports — they tell you what the caller actually did.</p>', 2),
('20000000-0000-0000-0000-000000000070', '10000000-0000-0000-0000-000000000017', 'hero_heading', '<h1>Report a Number</h1>', 0),
('20000000-0000-0000-0000-000000000071', '10000000-0000-0000-0000-000000000017', 'hero_subtext', '<p>Tell us what happened. Your report is checked by our moderation before it goes live — no login needed.</p>', 1),
('20000000-0000-0000-0000-000000000072', '10000000-0000-0000-0000-000000000018', 'tips_heading', '<h2>What makes a good report</h2>', 0),
('20000000-0000-0000-0000-000000000073', '10000000-0000-0000-0000-000000000018', 'tips_text', '<p>Write what the caller said, in your own words. Say whether they asked for a code, bank details, or threatened you. Do not include your own name, address, or any personal details.</p>', 1),
('20000000-0000-0000-0000-000000000074', '10000000-0000-0000-0000-000000000018', 'tips_h3', '<h3>What happens next</h3><p>Your report waits for moderation. Once approved, it appears on the number page and the spam score updates.</p>', 2),
('20000000-0000-0000-0000-000000000075', '10000000-0000-0000-0000-000000000019', 'hero_heading', '<h1>Privacy Policy</h1>', 0),
('20000000-0000-0000-0000-000000000076', '10000000-0000-0000-0000-000000000020', 'collect_heading', '<h2>What data we collect</h2>', 0),
('20000000-0000-0000-0000-000000000077', '10000000-0000-0000-0000-000000000020', 'collect_text', '<p>We collect the numbers people search for and report, the text of reports, and votes. We do not ask for your name, email or address to search or report a number.</p>', 1),
('20000000-0000-0000-0000-000000000078', '10000000-0000-0000-0000-000000000020', 'collect_h3', '<h3>What we never publish</h3><p>We never publish a number owner''s name or address, and we never publish personal details from a report.</p>', 2),
('20000000-0000-0000-0000-000000000079', '10000000-0000-0000-0000-000000000021', 'cookies_heading', '<h2>Cookies and analytics</h2>', 0),
('20000000-0000-0000-0000-000000000080', '10000000-0000-0000-0000-000000000021', 'cookies_text', '<p>We use cookies to keep the site working and to understand, in aggregate, which pages people visit. See the Cookie Policy for the full list.</p>', 1),
('20000000-0000-0000-0000-000000000081', '10000000-0000-0000-0000-000000000022', 'retention_heading', '<h2>How long we keep data</h2>', 0),
('20000000-0000-0000-0000-000000000082', '10000000-0000-0000-0000-000000000022', 'retention_text', '<p>Reports stay on the site because they are the warning for the next person. If a report is wrong, ask for a correction through the Contact Us page and we will review it.</p>', 1),
('20000000-0000-0000-0000-000000000083', '10000000-0000-0000-0000-000000000023', 'rights_heading', '<h2>Your rights</h2>', 0),
('20000000-0000-0000-0000-000000000084', '10000000-0000-0000-0000-000000000023', 'rights_text', '<p>If you believe a number that belongs to you is wrongly listed, contact us and we will review the reports and remove or correct them where they are wrong.</p>', 1),
('20000000-0000-0000-0000-000000000085', '10000000-0000-0000-0000-000000000024', 'hero_heading', '<h1>Terms &amp; Conditions</h1>', 0),
('20000000-0000-0000-0000-000000000086', '10000000-0000-0000-0000-000000000025', 'use_heading', '<h2>Using the site</h2>', 0),
('20000000-0000-0000-0000-000000000087', '10000000-0000-0000-0000-000000000025', 'use_text', '<p>You may search numbers and read reports for free. You may not use the site to harass anyone, or to collect numbers for spam.</p>', 1),
('20000000-0000-0000-0000-000000000088', '10000000-0000-0000-0000-000000000026', 'reports_heading', '<h2>Your reports</h2>', 0),
('20000000-0000-0000-0000-000000000089', '10000000-0000-0000-0000-000000000026', 'reports_text', '<p>When you submit a report, you confirm it is true to the best of your knowledge. False reports may be removed, and repeat abuse may be blocked.</p>', 1),
('20000000-0000-0000-0000-000000000090', '10000000-0000-0000-0000-000000000026', 'reports_h3', '<h3>Moderation</h3><p>We may edit or remove any report that is false, abusive, or contains personal details.</p>', 2),
('20000000-0000-0000-0000-000000000091', '10000000-0000-0000-0000-000000000027', 'score_heading', '<h2>The score is a signal, not a guarantee</h2>', 0),
('20000000-0000-0000-0000-000000000092', '10000000-0000-0000-0000-000000000027', 'score_text', '<p>The spam score is based on community reports. It is not proof that a number is safe or a scam. Always use your own judgement.</p>', 1),
('20000000-0000-0000-0000-000000000093', '10000000-0000-0000-0000-000000000028', 'liability_heading', '<h2>Liability</h2>', 0),
('20000000-0000-0000-0000-000000000094', '10000000-0000-0000-0000-000000000028', 'liability_text', '<p>We provide the site as it is. We are not responsible for decisions you make based on a score or a report.</p>', 1),
('20000000-0000-0000-0000-000000000095', '10000000-0000-0000-0000-000000000029', 'changes_heading', '<h2>Changes to these terms</h2>', 0),
('20000000-0000-0000-0000-000000000096', '10000000-0000-0000-0000-000000000029', 'changes_text', '<p>We may update these terms from time to time. The version on this page is the current one.</p>', 1),
('20000000-0000-0000-0000-000000000097', '10000000-0000-0000-0000-000000000030', 'hero_heading', '<h1>Disclaimer</h1>', 0),
('20000000-0000-0000-0000-000000000098', '10000000-0000-0000-0000-000000000031', 'dscore_heading', '<h2>The score is a signal, not a guarantee</h2>', 0),
('20000000-0000-0000-0000-000000000099', '10000000-0000-0000-0000-000000000031', 'dscore_text', '<p>A low score does not prove a number is safe. A high score does not prove a crime was committed. The score summarises community reports only.</p>', 1),
('20000000-0000-0000-0000-000000000100', '10000000-0000-0000-0000-000000000031', 'dscore_h3', '<h3>Read the reports, not just the number</h3><p>Two numbers can share a score for different reasons. The reports on the page explain why a number scored the way it did.</p>', 2),
('20000000-0000-0000-0000-000000000101', '10000000-0000-0000-0000-000000000032', 'loc_heading', '<h2>Caller location is always unknown</h2>', 0),
('20000000-0000-0000-0000-000000000102', '10000000-0000-0000-0000-000000000032', 'loc_text', '<p>We show where a number was allocated, not where the caller is. Caller ID can be spoofed, so a London number can be dialled from anywhere in the world.</p>', 1),
('20000000-0000-0000-0000-000000000103', '10000000-0000-0000-0000-000000000032', 'loc_h3', '<h3>Why we do not show a city as the caller location</h3><p>Showing a city would look precise and be wrong most of the time. Unknown is the honest answer.</p>', 2),
('20000000-0000-0000-0000-000000000104', '10000000-0000-0000-0000-000000000033', 'advice_heading', '<h2>Not financial or legal advice</h2>', 0),
('20000000-0000-0000-0000-000000000105', '10000000-0000-0000-0000-000000000033', 'advice_text', '<p>Nothing on this site is financial or legal advice. If you think you have been scammed, contact your bank and Action Fraud.</p>', 1),
('20000000-0000-0000-0000-000000000106', '10000000-0000-0000-0000-000000000034', 'verify_heading', '<h2>Always verify with the official body</h2>', 0),
('20000000-0000-0000-0000-000000000107', '10000000-0000-0000-0000-000000000034', 'verify_text', '<p>If a caller claims to be from HMRC, your bank, or any official body, hang up and contact that organisation through its official number — never through a number the caller gave you.</p>', 1),
('20000000-0000-0000-0000-000000000108', '10000000-0000-0000-0000-000000000035', 'hero_heading', '<h1>Cookie Policy</h1>', 0),
('20000000-0000-0000-0000-000000000109', '10000000-0000-0000-0000-000000000036', 'what_heading', '<h2>What cookies are</h2>', 0),
('20000000-0000-0000-0000-000000000110', '10000000-0000-0000-0000-000000000036', 'what_text', '<p>Cookies are small files stored in your browser. They remember settings and help us understand how the site is used.</p>', 1),
('20000000-0000-0000-0000-000000000111', '10000000-0000-0000-0000-000000000037', 'types_heading', '<h2>Which cookies we use</h2>', 0),
('20000000-0000-0000-0000-000000000112', '10000000-0000-0000-0000-000000000037', 'types_h3_1', '<h3>Necessary cookies</h3><p>These keep the site working, for example remembering your vote on a number.</p>', 1),
('20000000-0000-0000-0000-000000000113', '10000000-0000-0000-0000-000000000037', 'types_h3_2', '<h3>Analytics cookies</h3><p>These tell us, in aggregate, which pages people visit. They do not identify you.</p>', 2),
('20000000-0000-0000-0000-000000000114', '10000000-0000-0000-0000-000000000037', 'types_h3_3', '<h3>Advertising cookies</h3><p>If advertising is shown in future, the advertising provider may set its own cookies. We do not control those.</p>', 3),
('20000000-0000-0000-0000-000000000115', '10000000-0000-0000-0000-000000000038', 'control_heading', '<h2>How to turn cookies off</h2>', 0),
('20000000-0000-0000-0000-000000000116', '10000000-0000-0000-0000-000000000038', 'control_text', '<p>You can block or delete cookies in your browser settings. The site will still work, but some features may not remember your choices.</p>', 1),
('20000000-0000-0000-0000-000000000117', '10000000-0000-0000-0000-000000000039', 'hero_heading', '<h1>Top Reported Numbers</h1>', 0),
('20000000-0000-0000-0000-000000000118', '10000000-0000-0000-0000-000000000039', 'hero_subtext', '<p>The numbers with the most reports in the last 30 days, sorted by reports and spam score. The list updates automatically as new reports are approved.</p>', 1),
('20000000-0000-0000-0000-000000000119', '10000000-0000-0000-0000-000000000040', 'hero_heading', '<h1>Latest Reports</h1>', 0),
('20000000-0000-0000-0000-000000000120', '10000000-0000-0000-0000-000000000040', 'hero_subtext', '<p>The newest approved reports, most recent first. Each report is written by a real person who got the call.</p>', 1),
('20000000-0000-0000-0000-000000000121', '10000000-0000-0000-0000-000000000041', 'hero_heading', '<h1>Reverse Phone Lookup UK</h1>', 0),
('20000000-0000-0000-0000-000000000122', '10000000-0000-0000-0000-000000000041', 'hero_subtext', '<p>Reverse phone lookup means starting with a number and finding out what is known about it. In the UK, that is a lot less — and a lot more honest — than the paid sites promise.</p>', 1),
('20000000-0000-0000-0000-000000000123', '10000000-0000-0000-0000-000000000042', 'get_heading', '<h2>What you get in the UK</h2>', 0),
('20000000-0000-0000-0000-000000000124', '10000000-0000-0000-0000-000000000042', 'get_h3_1', '<h3>Number origin and type</h3><p>Where the number was allocated, and whether it is a landline, mobile, freephone or VoIP range.</p>', 1),
('20000000-0000-0000-0000-000000000125', '10000000-0000-0000-0000-000000000042', 'get_h3_2', '<h3>Community reports and a spam score</h3><p>What other people said about the caller, and a score built only from that evidence.</p>', 2),
('20000000-0000-0000-0000-000000000126', '10000000-0000-0000-0000-000000000043', 'not_heading', '<h2>What you do NOT get</h2>', 0),
('20000000-0000-0000-0000-000000000127', '10000000-0000-0000-0000-000000000043', 'not_text', '<p>You do not get the owner''s name or address. In the UK that information is not public, and any site that sells it to you is selling data of doubtful legality. We never publish it.</p>', 1),
('20000000-0000-0000-0000-000000000128', '10000000-0000-0000-0000-000000000043', 'not_h3', '<h3>Free vs paid</h3><p>Paid data brokers mainly sell US data. For a UK number, the honest free check — origin, type, reports, score — is usually all you need.</p>', 2),
('20000000-0000-0000-0000-000000000129', '10000000-0000-0000-0000-000000000044', 'how_heading', '<h2>How to check a number</h2>', 0),
('20000000-0000-0000-0000-000000000130', '10000000-0000-0000-0000-000000000044', 'how_text', '<p>Search the number on the <a href="/">homepage</a>. Read the reports. If there are none, treat the number as Unknown and be careful. Then vote or report it yourself.</p>', 1),
('20000000-0000-0000-0000-000000000131', '10000000-0000-0000-0000-000000000045', 'hero_heading', '<h1>Scam Calls</h1>', 0),
('20000000-0000-0000-0000-000000000132', '10000000-0000-0000-0000-000000000045', 'hero_subtext', '<p>Scam calls follow a small number of scripts. Learn the scripts, and the call stops working on you.</p>', 1),
('20000000-0000-0000-0000-000000000133', '10000000-0000-0000-0000-000000000046', 'types_heading', '<h2>The main scam call types</h2>', 0),
('20000000-0000-0000-0000-000000000134', '10000000-0000-0000-0000-000000000046', 'types_h3_1', '<h3>HMRC and tax scams</h3><p>Recorded messages about unpaid tax, arrest warrants and suspended National Insurance numbers. HMRC never works this way — see the <a href="/scam-calls/hmrc-scam-calls/">HMRC scam calls</a> page.</p>', 1),
('20000000-0000-0000-0000-000000000135', '10000000-0000-0000-0000-000000000046', 'types_h3_2', '<h3>Bank scams</h3><p>Callers pretending to be your bank, asking you to move money to a safe account. Real banks never ask this — see the <a href="/scam-calls/bank-scam-calls/">bank scam calls</a> page.</p>', 2),
('20000000-0000-0000-0000-000000000136', '10000000-0000-0000-0000-000000000046', 'types_h3_3', '<h3>Delivery and parcel scams</h3><p>Texts and calls about a missed delivery, with a link to pay a small fee. The link steals your card details.</p>', 3),
('20000000-0000-0000-0000-000000000137', '10000000-0000-0000-0000-000000000047', 'signs_heading', '<h2>Universal warning signs</h2>', 0),
('20000000-0000-0000-0000-000000000138', '10000000-0000-0000-0000-000000000047', 'signs_text', '<p>Urgency ("act now or else"), secrecy ("do not tell your bank"), and a request for a code, a password, or a payment by gift card or bank transfer. Any one of these is enough to hang up.</p>', 1),
('20000000-0000-0000-0000-000000000139', '10000000-0000-0000-0000-000000000048', 'do_heading', '<h2>What to do when a scam call comes in</h2>', 0),
('20000000-0000-0000-0000-000000000140', '10000000-0000-0000-0000-000000000048', 'do_text', '<p>Hang up. Do not press 1, do not call back the number they gave you. If it was a bank scam, call 159. If it was a text, forward it to 7726. Then <a href="/report-a-number/">report the number</a> here.</p>', 1),
('20000000-0000-0000-0000-000000000141', '10000000-0000-0000-0000-000000000049', 'hero_heading', '<h1>HMRC Scam Calls</h1>', 0),
('20000000-0000-0000-0000-000000000142', '10000000-0000-0000-0000-000000000049', 'hero_subtext', '<p>HMRC scam calls are the most reported scam in the UK. They all follow the same scripts — and HMRC never uses any of them.</p>', 1),
('20000000-0000-0000-0000-000000000143', '10000000-0000-0000-0000-000000000050', 'scripts_heading', '<h2>The three HMRC scripts</h2>', 0),
('20000000-0000-0000-0000-000000000144', '10000000-0000-0000-0000-000000000050', 'scripts_h3_1', '<h3>1. The recorded message</h3><p>A robot voice says a tax case has been opened and you must press 1 to speak to an officer.</p>', 1),
('20000000-0000-0000-0000-000000000145', '10000000-0000-0000-0000-000000000050', 'scripts_h3_2', '<h3>2. The returned letter</h3><p>A letter was returned undelivered, so legal action is starting. It never was.</p>', 2),
('20000000-0000-0000-0000-000000000146', '10000000-0000-0000-0000-000000000050', 'scripts_h3_3', '<h3>3. The arrest threat</h3><p>A warrant has been issued and police are on their way unless you pay now. HMRC does not arrest people by phone.</p>', 3),
('20000000-0000-0000-0000-000000000147', '10000000-0000-0000-0000-000000000051', 'real_heading', '<h2>What HMRC actually does</h2>', 0),
('20000000-0000-0000-0000-000000000148', '10000000-0000-0000-0000-000000000051', 'real_text', '<p>HMRC writes to you by post. It never robocalls you, never calls from a mobile number, never asks for payment by gift card, and never threatens arrest on a call. Its real contact number is 0300 200 3300.</p>', 1),
('20000000-0000-0000-0000-000000000149', '10000000-0000-0000-0000-000000000052', 'if_heading', '<h2>If you got an HMRC scam call</h2>', 0),
('20000000-0000-0000-0000-000000000150', '10000000-0000-0000-0000-000000000052', 'if_text', '<p>Hang up, do not press 1, and do not pay anything. Report the number here, and forward any related scam text to 7726. If you already paid, call your bank immediately and report it to Action Fraud.</p>', 1),
('20000000-0000-0000-0000-000000000151', '10000000-0000-0000-0000-000000000053', 'hero_heading', '<h1>Bank Scam Calls</h1>', 0),
('20000000-0000-0000-0000-000000000152', '10000000-0000-0000-0000-000000000053', 'hero_subtext', '<p>A caller says they are from your bank and your money is at risk. It sounds urgent and official. It is the most expensive scam in the UK.</p>', 1),
('20000000-0000-0000-0000-000000000153', '10000000-0000-0000-0000-000000000054', 'bscripts_heading', '<h2>The bank scam scripts</h2>', 0),
('20000000-0000-0000-0000-000000000154', '10000000-0000-0000-0000-000000000054', 'bscripts_h3_1', '<h3>The safe account</h3><p>Move your money to a safe account while we investigate. The safe account belongs to the scammer.</p>', 1),
('20000000-0000-0000-0000-000000000155', '10000000-0000-0000-0000-000000000054', 'bscripts_h3_2', '<h3>The suspicious payment</h3><p>A large payment is about to leave your account. Confirm your details so we can stop it.</p>', 2),
('20000000-0000-0000-0000-000000000156', '10000000-0000-0000-0000-000000000054', 'bscripts_h3_3', '<h3>The code check</h3><p>Read out the code we just sent you, so we know it is really you. That code lets them into your account.</p>', 3),
('20000000-0000-0000-0000-000000000157', '10000000-0000-0000-0000-000000000055', 'never_heading', '<h2>What your bank will never ask</h2>', 0),
('20000000-0000-0000-0000-000000000158', '10000000-0000-0000-0000-000000000055', 'never_text', '<p>Your bank will never ask for your full password, your PIN, or a one-time code on a call. It will never ask you to move money to a safe account, and never ask you to download software during a call.</p>', 1),
('20000000-0000-0000-0000-000000000159', '10000000-0000-0000-0000-000000000056', 'n159_heading', '<h2>If you get a bank scam call, call 159</h2>', 0),
('20000000-0000-0000-0000-000000000160', '10000000-0000-0000-0000-000000000056', 'n159_text', '<p>Hang up. Then dial 159 yourself — it connects you to your own bank''s fraud team. Never call back a number the caller gave you. Read the full 159 guide in our blog: <a href="/blog/159-bank-scam-number/">159: the number to call if a bank scam call comes in</a>.</p>', 1),
('20000000-0000-0000-0000-000000000161', '10000000-0000-0000-0000-000000000057', 'hero_heading', '<h1>Area Codes</h1>', 0),
('20000000-0000-0000-0000-000000000162', '10000000-0000-0000-0000-000000000057', 'hero_subtext', '<p>An area code tells you where a number was allocated. It does not tell you where the caller is.</p>', 1),
('20000000-0000-0000-0000-000000000163', '10000000-0000-0000-0000-000000000058', 'geo_heading', '<h2>Geographic area codes</h2>', 0),
('20000000-0000-0000-0000-000000000164', '10000000-0000-0000-0000-000000000058', 'geo_text', '<p>020 is London, 0161 is Manchester, 0121 is Birmingham, 0131 is Edinburgh, 0113 is Leeds. These numbers belong to a place — but the caller can be anywhere, because caller ID can be spoofed.</p>', 1),
('20000000-0000-0000-0000-000000000165', '10000000-0000-0000-0000-000000000059', 'nongeo_heading', '<h2>Non-geographic ranges</h2>', 0),
('20000000-0000-0000-0000-000000000166', '10000000-0000-0000-0000-000000000059', 'nongeo_h3_1', '<h3>07 — UK mobiles</h3><p>The most common range in the UK, and the most spoofed by scammers pretending to be HMRC or a delivery company.</p>', 1),
('20000000-0000-0000-0000-000000000167', '10000000-0000-0000-0000-000000000059', 'nongeo_h3_2', '<h3>0800 — freephone</h3><p>Free to call. Used by real companies and by telemarketers.</p>', 2),
('20000000-0000-0000-0000-000000000168', '10000000-0000-0000-0000-000000000059', 'nongeo_h3_3', '<h3>03 — UK-wide</h3><p>Charged at the standard rate. Used by government departments, banks and large companies — and by scammers copying them.</p>', 3),
('20000000-0000-0000-0000-000000000169', '10000000-0000-0000-0000-000000000059', 'nongeo_h3_4', '<h3>070 — personal numbers</h3><p>Expensive to call back and often used in scams. Be very careful with 070 numbers.</p>', 4),
('20000000-0000-0000-0000-000000000170', '10000000-0000-0000-0000-000000000060', 'use_heading', '<h2>How to use an area code sensibly</h2>', 0),
('20000000-0000-0000-0000-000000000171', '10000000-0000-0000-0000-000000000060', 'use_text', '<p>Use the area code as a first clue, then search the number itself. The reports on the number page matter far more than the prefix.</p>', 1),
('20000000-0000-0000-0000-000000000172', '10000000-0000-0000-0000-000000000061', 'hero_heading', '<h1>London — 020</h1>', 0),
('20000000-0000-0000-0000-000000000173', '10000000-0000-0000-0000-000000000061', 'hero_subtext', '<p>020 is the area code for London. It is also one of the most spoofed prefixes in the UK.</p>', 1),
('20000000-0000-0000-0000-000000000174', '10000000-0000-0000-0000-000000000062', 'what_heading', '<h2>What 020 means</h2>', 0),
('20000000-0000-0000-0000-000000000175', '10000000-0000-0000-0000-000000000062', 'what_text', '<p>A 020 number was allocated in London. That is all it means. It does not mean the caller is in London, works in London, or is who they say they are.</p>', 1),
('20000000-0000-0000-0000-000000000176', '10000000-0000-0000-0000-000000000062', 'what_h3', '<h3>020 numbers are also used by real London businesses</h3><p>Not every 020 call is a scam. Check the number itself — the reports tell you which ones are.</p>', 2),
('20000000-0000-0000-0000-000000000177', '10000000-0000-0000-0000-000000000063', 'spoof_heading', '<h2>Why scammers love 020</h2>', 0),
('20000000-0000-0000-0000-000000000178', '10000000-0000-0000-0000-000000000063', 'spoof_text', '<p>London sounds official. A scam call from a 020 number feels more trustworthy than one from an unknown mobile — which is exactly why scammers spoof it. Read our full guide: <a href="/blog/020-number-spoofing/">Why a London (020) number can call you from abroad</a>.</p>', 1),
('20000000-0000-0000-0000-000000000179', '10000000-0000-0000-0000-000000000063', 'spoof_h3', '<h3>The story is the giveaway, not the prefix</h3><p>An HMRC call from a London number that asks you to press 1 is a scam — HMRC never works that way, whatever the number looks like.</p>', 2),
('20000000-0000-0000-0000-000000000180', '10000000-0000-0000-0000-000000000064', 'check_heading', '<h2>How to check a 020 number</h2>', 0),
('20000000-0000-0000-0000-000000000181', '10000000-0000-0000-0000-000000000064', 'check_text', '<p>Search the full number on the <a href="/">homepage</a>. If other people reported it, you will see the reports and the score. If there are no reports, treat it as Unknown.</p>', 1),
('20000000-0000-0000-0000-000000000182', '10000000-0000-0000-0000-000000000065', 'hero_heading', '<h1>Mobile Numbers — 07 Range</h1>', 0),
('20000000-0000-0000-0000-000000000183', '10000000-0000-0000-0000-000000000065', 'hero_subtext', '<p>07 is the UK mobile range. Most scam calls in the UK come from 07 numbers — because most people trust a mobile number.</p>', 1),
('20000000-0000-0000-0000-000000000184', '10000000-0000-0000-0000-000000000066', 'mwhat_heading', '<h2>What 07 means</h2>', 0),
('20000000-0000-0000-0000-000000000185', '10000000-0000-0000-0000-000000000066', 'mwhat_text', '<p>07 numbers are UK mobiles. They are cheap to get, easy to replace, and hard to trace — which is why scammers use them and throw them away.</p>', 1),
('20000000-0000-0000-0000-000000000186', '10000000-0000-0000-0000-000000000067', 'mscams_heading', '<h2>Common 07 scams</h2>', 0),
('20000000-0000-0000-0000-000000000187', '10000000-0000-0000-0000-000000000067', 'mscams_h3_1', '<h3>HMRC from a mobile</h3><p>HMRC never calls from a mobile. Any HMRC call from an 07 number is a scam.</p>', 1),
('20000000-0000-0000-0000-000000000188', '10000000-0000-0000-0000-000000000067', 'mscams_h3_2', '<h3>Hi Mum / Hi Dad</h3><p>A text from a new number pretending to be your child, asking for money. Always call your child on their old number first.</p>', 2),
('20000000-0000-0000-0000-000000000189', '10000000-0000-0000-0000-000000000067', 'mscams_h3_3', '<h3>Delivery texts</h3><p>A missed delivery message with a link to pay a fee. The link steals your card details.</p>', 3),
('20000000-0000-0000-0000-000000000190', '10000000-0000-0000-0000-000000000068', 'mcheck_heading', '<h2>How to check an 07 number</h2>', 0),
('20000000-0000-0000-0000-000000000191', '10000000-0000-0000-0000-000000000068', 'mcheck_text', '<p>Search it on the <a href="/">homepage</a> before you reply or call back. A number with reports will show them; a number with none is Unknown, not Safe.</p>', 1),
('20000000-0000-0000-0000-000000000192', '10000000-0000-0000-0000-000000000069', 'hero_heading', '<h1>How to Report a Scam Call in the UK</h1>', 0),
('20000000-0000-0000-0000-000000000193', '10000000-0000-0000-0000-000000000069', 'hero_subtext', '<p>Reporting takes two minutes. It protects the next person — and it helps the networks and the police shut the scammers down.</p>', 1),
('20000000-0000-0000-0000-000000000194', '10000000-0000-0000-0000-000000000070', 'rsteps_heading', '<h2>Report it in three places</h2>', 0),
('20000000-0000-0000-0000-000000000195', '10000000-0000-0000-0000-000000000070', 'rsteps_h3_1', '<h3>1. Report the number here</h3><p>Use the <a href="/report-a-number/">Report a Number</a> form. Say what the caller said and what they asked for.</p>', 1),
('20000000-0000-0000-0000-000000000196', '10000000-0000-0000-0000-000000000070', 'rsteps_h3_2', '<h3>2. Forward scam texts to 7726</h3><p>Forward the message to 7726. It is free, and your network uses it to block the sender. Full guide: <a href="/blog/report-scam-text-7726/">How to report a scam text to 7726</a>.</p>', 2),
('20000000-0000-0000-0000-000000000197', '10000000-0000-0000-0000-000000000070', 'rsteps_h3_3', '<h3>3. Bank scam? Call 159. Lost money? Action Fraud</h3><p>If it was a bank scam, hang up and call 159. If you lost money, report it to Action Fraud (0300 123 2040) and your bank.</p>', 3),
('20000000-0000-0000-0000-000000000198', '10000000-0000-0000-0000-000000000071', 'happens_heading', '<h2>What happens after you report</h2>', 0),
('20000000-0000-0000-0000-000000000199', '10000000-0000-0000-0000-000000000071', 'happens_text', '<p>Your report is checked, then published on the number page. Other people who search the same number will see the warning before they answer or call back.</p>', 1),
('20000000-0000-0000-0000-000000000200', '10000000-0000-0000-0000-000000000072', 'ev_heading', '<h2>Keep the evidence</h2>', 0),
('20000000-0000-0000-0000-000000000201', '10000000-0000-0000-0000-000000000072', 'ev_text', '<p>Do not delete the call log or the text. Screenshot the message, note the date and time, and keep any payment records. Action Fraud and your bank may ask for them.</p>', 1),
('20000000-0000-0000-0000-000000000202', '10000000-0000-0000-0000-000000000073', 'draft_note', '<p><strong>Draft template — dummy content. Nomi will replace this text with the final post.</strong></p>', 0),
('20000000-0000-0000-0000-000000000203', '10000000-0000-0000-0000-000000000073', 'intro', '<h2>What 7726 is</h2><p>7726 is the UK''s free service for reporting scam texts. It is run by the mobile networks. It is for texts only — not for calls.</p>', 1),
('20000000-0000-0000-0000-000000000204', '10000000-0000-0000-0000-000000000073', 'steps', '<h2>How to forward a scam text to 7726</h2><h3>Step 1 — Forward, do not reply</h3><p>Forward the message to 7726. Do not reply to the sender and do not click any link in the message.</p><h3>Step 2 — Send the sender''s number if asked</h3><p>Your network may ask for the number the text came from. Send it exactly as shown.</p>', 2),
('20000000-0000-0000-0000-000000000205', '10000000-0000-0000-0000-000000000073', 'after', '<h2>What happens after you report</h2><p>Your network investigates the sender and can block the number. Reporting also helps the networks spot new scam campaigns early.</p>', 3),
('20000000-0000-0000-0000-000000000206', '10000000-0000-0000-0000-000000000073', 'free', '<h2>Is 7726 free?</h2><p>Yes. Forwarding a text to 7726 is free on all UK networks.</p>', 4),
('20000000-0000-0000-0000-000000000207', '10000000-0000-0000-0000-000000000074', 'closing', '<h2>Received one of these texts?</h2><p>Search the sender''s number on the <a href="/">homepage</a> to see if other people reported it too.</p>', 0),
('20000000-0000-0000-0000-000000000208', '10000000-0000-0000-0000-000000000075', 'draft_note', '<p><strong>Draft template — dummy content. Nomi will replace this text with the final post.</strong></p>', 0),
('20000000-0000-0000-0000-000000000209', '10000000-0000-0000-0000-000000000075', 'intro', '<h2>What 159 is</h2><p>159 is the Stop Scams UK number. When you dial it, you are connected to your own bank''s fraud team — the real one, not the caller.</p>', 1),
('20000000-0000-0000-0000-000000000210', '10000000-0000-0000-0000-000000000075', 'when', '<h2>When to call 159</h2><h3>A bank call that feels wrong</h3><p>If a caller says they are from your bank and asks you to move money, share a code, or confirm details, hang up first — then dial 159 yourself.</p>', 2),
('20000000-0000-0000-0000-000000000211', '10000000-0000-0000-0000-000000000075', 'what', '<h2>What happens when you call 159</h2><p>You choose your bank from a menu and speak to its fraud team. They can check your account and stop a payment if it is still in time.</p>', 3),
('20000000-0000-0000-0000-000000000212', '10000000-0000-0000-0000-000000000075', 'never', '<h2>Never call back the caller''s number</h2><p>Always dial 159 yourself from your own phone. A number the caller gave you may go straight back to the scammers.</p>', 4),
('20000000-0000-0000-0000-000000000213', '10000000-0000-0000-0000-000000000076', 'closing', '<h2>Received one of these calls?</h2><p>Search the number on the <a href="/">homepage</a> and report it so the next person is warned.</p>', 0),
('20000000-0000-0000-0000-000000000214', '10000000-0000-0000-0000-000000000077', 'draft_note', '<p><strong>Draft template — dummy content. Nomi will replace this text with the final post.</strong></p>', 0),
('20000000-0000-0000-0000-000000000215', '10000000-0000-0000-0000-000000000077', 'intro', '<h2>Blocking, in short</h2><p>Blocking stops that number from calling you again. It does not stop the scammers — they change numbers. Report the number too, so others are warned.</p>', 1),
('20000000-0000-0000-0000-000000000216', '10000000-0000-0000-0000-000000000077', 'iphone', '<h2>Block on iPhone</h2><h3>From Recents</h3><p>Open Phone, tap Recents, tap the i next to the number, then Block this Caller. You can also turn on Silence Unknown Callers in Settings, Phone.</p>', 2),
('20000000-0000-0000-0000-000000000217', '10000000-0000-0000-0000-000000000077', 'android', '<h2>Block on Android</h2><h3>From the Phone app</h3><p>Open Phone, tap Recents, tap the number, then Block. On Samsung phones the option is in the call details menu.</p>', 3),
('20000000-0000-0000-0000-000000000218', '10000000-0000-0000-0000-000000000077', 'after', '<h2>What happens after you block a number</h2><p>The number can no longer call or text you. The caller hears nothing useful — and you hear nothing at all.</p>', 4),
('20000000-0000-0000-0000-000000000219', '10000000-0000-0000-0000-000000000078', 'closing', '<h2>Blocked it? Report it too</h2><p>Search the number on the <a href="/">homepage</a> and add a report, so the next person who gets the call sees the warning.</p>', 0),
('20000000-0000-0000-0000-000000000220', '10000000-0000-0000-0000-000000000079', 'draft_note', '<p><strong>Draft template — dummy content. Nomi will replace this text with the final post.</strong></p>', 0),
('20000000-0000-0000-0000-000000000221', '10000000-0000-0000-0000-000000000079', 'intro', '<h2>First: do not call back straight away</h2><p>A missed call from a number you do not know is not an emergency. Check the number first — it takes ten seconds.</p>', 1),
('20000000-0000-0000-0000-000000000222', '10000000-0000-0000-0000-000000000079', 'checks', '<h2>Three checks before you call back</h2><h3>Check 1 — Search the number</h3><p>Search it on the <a href="/">homepage</a>. If other people reported it as a scam, do not call back.</p><h3>Check 2 — Look at the prefix</h3><p>A 070 number or a foreign-looking number is a warning sign. Calling back can be expensive.</p><h3>Check 3 — Think about what you are expecting</h3><p>Are you waiting for a delivery, a doctor, or a job call? If not, there is no reason to call back.</p>', 2),
('20000000-0000-0000-0000-000000000223', '10000000-0000-0000-0000-000000000079', 'onering', '<h2>The one-ring missed call scam</h2><p>Your phone rings once and stops. The scammer wants you to call back a premium-rate number. If it rang once and you do not know the number, do not call back.</p>', 3),
('20000000-0000-0000-0000-000000000224', '10000000-0000-0000-0000-000000000079', 'when', '<h2>When it is safe to call back</h2><p>When the number has no reports, looks like a normal UK number, and you are expecting a call — then it is probably fine.</p>', 4),
('20000000-0000-0000-0000-000000000225', '10000000-0000-0000-0000-000000000080', 'closing', '<h2>Got a missed call just now?</h2><p>Search the number on the <a href="/">homepage</a> before you decide.</p>', 0),
('20000000-0000-0000-0000-000000000226', '10000000-0000-0000-0000-000000000081', 'draft_note', '<p><strong>Draft template — dummy content. Nomi will replace this text with the final post.</strong></p>', 0),
('20000000-0000-0000-0000-000000000227', '10000000-0000-0000-0000-000000000081', 'intro', '<h2>What spoofing is</h2><p>Caller ID spoofing is when a caller makes any number they like appear on your phone. The number you see is not proof of where the caller is, or who they are.</p>', 1),
('20000000-0000-0000-0000-000000000228', '10000000-0000-0000-0000-000000000081', 'why', '<h2>Why scammers spoof 020</h2><h3>London sounds official</h3><p>A London number feels trustworthy. A scammer in another country can show a 020 number in seconds, using cheap internet calling software.</p>', 2),
('20000000-0000-0000-0000-000000000229', '10000000-0000-0000-0000-000000000081', 'signs', '<h2>How to spot a spoofed call</h2><h3>The story does not match the number</h3><p>HMRC calling from a London landline but asking you to press 1? A bank calling from 020 but asking for your code? The number is real-looking; the story is the giveaway.</p>', 3),
('20000000-0000-0000-0000-000000000230', '10000000-0000-0000-0000-000000000081', 'todo', '<h2>What to do</h2><p>Hang up and call the organisation back on its official number. Search the number here first, and report it if it was a scam.</p>', 4),
('20000000-0000-0000-0000-000000000231', '10000000-0000-0000-0000-000000000082', 'closing', '<h2>Got a call from a 020 number you do not know?</h2><p>Search it on the <a href="/">homepage</a> and read the reports before you call back.</p>', 0)
