insert into reports (number, body, category, asked_otp, asked_bank_details, used_threat, status, created_at) values
('08007613372', 'Caller said they were from Sky and offered a cheaper TV and broadband deal. They asked for bank details to set up the new package. The number is reported by many people as Sky telemarketing.', 'telemarketing', false, true, false, 'approved', '2026-11-19'),
('08007613372', 'A recorded message about a Sky discount, then a person tried to confirm my account details. I did not give anything.', 'telemarketing', false, true, false, 'approved', '2026-11-17'),
('02079460958', 'Caller claimed to be from an investment recovery firm and said they could get back money lost to a scam, for a fee paid in advance. This is a classic recovery scam.', 'scam', false, true, false, 'approved', '2026-11-18'),
('02079460958', 'They knew my name and said my investment had been recovered. They wanted a release fee by bank transfer.', 'scam', false, true, false, 'approved', '2026-11-15'),
('07379885614', 'Recorded message claiming to be HMRC. It said a tax fraud case had been opened against me and I should press 1 to speak to an officer. HMRC never contacts people this way.', 'scam', false, false, true, 'approved', '2026-11-20'),
('02045376782', 'Caller said they were from a housing association and needed to check my address and bank details for a repair visit. I do not live in housing association property.', 'scam', false, true, false, 'approved', '2026-11-19'),
('02035661067', 'Caller offered free loft insulation under a government scheme and asked for personal details and a survey appointment. The call followed the usual loft insulation scam script.', 'scam', false, false, false, 'approved', '2026-11-18'),
('03332029470', 'Caller said they were from British Gas and my account was in arrears. They asked me to pay by bank transfer to avoid disconnection.', 'scam', false, true, true, 'approved', '2026-11-19'),
('07364165789', 'Missed call, then a text saying I had won a prize and should call back. Calling back a premium-rate number can cost a lot — this looks like a cost trap.', 'scam', false, false, false, 'approved', '2026-11-16'),
('07441955492', 'Caller offered guaranteed returns on a crypto investment and pushed me to deposit money the same day through a link they sent.', 'scam', false, true, false, 'approved', '2026-11-18'),
('07394513075', 'Caller claimed to be from a job agency with a work-from-home job. They asked for a training fee before I could start.', 'scam', false, true, false, 'approved', '2026-11-15'),
('07441933356', 'Added me to a WhatsApp group promising daily trading profits. The group was full of fake success stories and links to deposit money.', 'scam', false, true, false, 'approved', '2026-11-17'),
('07860043075', 'Text and call pretending to be a delivery company, saying a parcel could not be delivered and asking me to click a link and pay a redelivery fee.', 'scam', false, true, false, 'approved', '2026-11-20'),
('07846846431', 'Caller talked about a political survey, then kept calling back several times in one day even after I asked them to stop.', 'spam', false, false, false, 'approved', '2026-11-17'),
('07537453904', 'This number has been reported by community members, but no confirmed scam pattern has been found for it yet. Treat it as unknown and check back if more reports appear.', 'other', false, false, false, 'approved', '2026-11-11'),
('02046131964', 'This number has been reported by community members, but no confirmed scam pattern has been found for it yet. Treat it as unknown and check back if more reports appear.', 'other', false, false, false, 'approved', '2026-11-10'),
('03330046113', 'This number has been reported by community members, but no confirmed scam pattern has been found for it yet. Treat it as unknown and check back if more reports appear.', 'other', false, false, false, 'approved', '2026-11-08'),
('07887825391', 'Recorded HMRC message: a letter was returned undelivered and legal action was about to start. Press 1 for an officer. HMRC never threatens arrest by phone and never calls from a mobile.', 'scam', false, false, true, 'approved', '2026-11-19'),
('07410637126', 'Caller said they were HMRC and I owed tax. They demanded immediate payment by gift card or bank transfer.', 'scam', false, true, true, 'approved', '2026-11-18'),
